<script>
(() => { const list=document.getElementById('quoteItems'), template=document.getElementById('quoteItemTemplate'), money=v=>v.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}); let next=list.querySelectorAll('.quote-item').length; const refresh=()=>{let subtotal=0,cost=0;list.querySelectorAll('.quote-item').forEach(row=>{const q=Number(row.querySelector('[name*=quantity]').value)||0,p=Number(row.querySelector('.item-price').value)||0,c=Number(row.querySelector('.item-cost').value)||0;subtotal+=q*p;cost+=q*c;row.querySelector('.line-total').textContent=money(q*p)});const discount=Number(document.getElementById('discount').value)||0,total=Math.max(0,subtotal-discount),margin=total?((total-cost)/total)*100:0;document.getElementById('subtotalPreview').textContent=money(subtotal);document.getElementById('costPreview').textContent=money(cost);document.getElementById('totalPreview').textContent=money(total);const marginEl=document.getElementById('marginPreview');marginEl.textContent=margin.toFixed(1).replace('.',',')+'%';marginEl.className=margin<20?'negative':''};const wire=row=>{row.querySelectorAll('.calc-input').forEach(i=>i.addEventListener('input',refresh));row.querySelector('.product-select').addEventListener('change',e=>{const o=e.target.selectedOptions[0];if(o.value){row.querySelector('.item-description').value=o.dataset.name;row.querySelector('.item-price').value=o.dataset.price;row.querySelector('.item-cost').value=o.dataset.cost}refresh()});row.querySelector('.remove-item').addEventListener('click',()=>{if(list.children.length>1){row.remove();refresh()}})};list.querySelectorAll('.quote-item').forEach(wire);document.getElementById('addItem').addEventListener('click',()=>{list.insertAdjacentHTML('beforeend',template.innerHTML.replaceAll('__INDEX__',next++));wire(list.lastElementChild);refresh()});document.getElementById('discount').addEventListener('input',refresh);refresh()})()
</script>
